 88	// NewPromptTokenCounter counts prompt tokens using cl100k_base.
 89	func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
 90		tokenizer := codec.NewCl100kBase()
 91		count := 0
 92		for _, message := range messages {
 93			tokens, _, err := tokenizer.Encode(message.Content)
 94			if err != nil {
 95				return nil, trace.Wrap(err)
 96			}
 97			count += perMessage + perRole + len(tokens)
 98		}
 99		return &StaticTokenCounter{count: count}, nil
100	}
