102	// NewSynchronousTokenCounter counts a complete response using cl100k_base.
103	func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
104		tokens, _, err := codec.NewCl100kBase().Encode(completion)
105		if err != nil {
106			return nil, trace.Wrap(err)
107		}
108		return &StaticTokenCounter{count: perRequest + len(tokens)}, nil
