111	// AsynchronousTokenCounter counts completion tokens as stream chunks arrive.
112	type AsynchronousTokenCounter struct {
113		mu       sync.Mutex
114		count    int
115		finished bool
116	}
117	
118	// NewAsynchronousTokenCounter initializes a streaming counter with its first fragment.
119	func NewAsynchronousTokenCounter(start string) (*AsynchronousTokenCounter, error) {
120		tokens, _, err := codec.NewCl100kBase().Encode(start)
121		if err != nil {
122			return nil, trace.Wrap(err)
123		}
124		return &AsynchronousTokenCounter{count: len(tokens)}, nil
125	}
126	
127	// Add increments the streamed token count by one.
128	func (c *AsynchronousTokenCounter) Add() error {
129		if c == nil {
130			return trace.Errorf("cannot add to a nil token counter")
131		}
132		c.mu.Lock()
133		defer c.mu.Unlock()
134		if c.finished {
135			return trace.Errorf("token counter has already been finalized")
136		}
137		c.count++
138		return nil
139	}
140	
141	// TokenCount finalizes the counter and returns its value including request overhead.
142	func (c *AsynchronousTokenCounter) TokenCount() int {
143		if c == nil {
144			return perRequest
145		}
146		c.mu.Lock()
147		defer c.mu.Unlock()
148		c.finished = true
149		return perRequest + c.count
150	}
